// Pixel widths of ASCII 32..126 in the screen fonts s16 and s20, copied from agent-gadget/esp32_agent_gadget/font_metrics.h
// (generated by tools/make_font_metrics.py). The page measures text with these, so text is cut and wrapped exactly like the gadget.
export const FONT_S16_W = [4, 4, 6, 8, 7, 11, 9, 3, 4, 4, 6, 9, 3, 5, 3, 5, 7, 5, 7, 7, 7, 7, 7, 7, 7, 7, 3, 3, 9, 9, 9, 6, 12, 9, 8, 8, 9, 7, 7, 9, 10, 4, 5, 8, 6, 12, 10, 10, 8, 10, 8, 7, 7, 9, 8, 13, 8, 8, 8, 4, 5, 4, 9, 5, 4, 7, 8, 6, 8, 7, 4, 8, 8, 3, 3, 7, 3, 12, 8, 8, 8, 8, 5, 6, 5, 8, 7, 10, 7, 7, 6, 4, 4, 4, 9];
export const FONT_S20_W = [4, 5, 7, 9, 9, 13, 13, 4, 6, 6, 7, 11, 4, 6, 4, 7, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 4, 4, 11, 11, 11, 7, 14, 11, 10, 9, 11, 8, 8, 11, 11, 5, 7, 10, 8, 14, 12, 11, 9, 11, 10, 8, 9, 11, 10, 15, 10, 9, 9, 6, 7, 6, 11, 6, 5, 8, 9, 7, 9, 8, 6, 9, 9, 4, 4, 8, 4, 14, 9, 9, 9, 9, 6, 7, 6, 9, 8, 12, 8, 8, 7, 6, 5, 6, 11];

/** Width in pixels of `s` on the screen (font 16 or 20), as displayTextPx of the firmware. */
export function textWidth(s, font) {
  const w = font === 20 ? FONT_S20_W : FONT_S16_W;
  let px = 0;
  for (const ch of String(s)) {
    const c = ch.codePointAt(0);
    px += w[c >= 32 && c <= 126 ? c - 32 : 0];
  }
  return px;
}
